from functools import lru_cache

def can_form_subset(nums, target):
    @lru_cache(None)
    def dfs(index, current_sum):
        if current_sum >= target:
            return True
        if index == len(nums):
            return False
        return dfs(index + 1, current_sum + nums[index]) or dfs(index + 1, current_sum)

    return dfs(0, 0)

