from sys import stdin, stdout

def count_unnecessary_cards(N, K, a):
    dp = [False] * (K + 1)
    dp[0] = True

    for num in a:
        new_dp = dp[:]
        for j in range(K, num - 1, -1):
            if dp[j - num]:
                new_dp[j] = True
        dp = new_dp

    unnecessary_count = 0
    for i in range(N):
        if all(not dp[j] for j in range(K, a[i] - 1, -1)):
            unnecessary_count += 1

    return unnecessary_count

